import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;

public class Week_Week_TriageGen2Test {





    @Test
    public void testEqualsAndHashCode() {
        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.MAY, 10);
        Date date = cal.getTime();
        TimeZone zone = TimeZone.getTimeZone("GMT");

        Week week1 = new Week(date, zone);
        Week week2 = new Week(date, zone);
        Week week3 = new Week(2024, 1);

        assertEquals(week1, week2);
        assertEquals(week1.hashCode(), week2.hashCode());
        assertNotEquals(week1, week3);
        assertNotEquals(week1, null);
        assertNotEquals(week1, "not a week object");
    }












}

